<script setup lang="ts">
import {ref} from 'vue';import {useRouter} from 'vue-router';import {useAuth} from '../stores/auth';import {DEMO_ACCOUNTS,DEMO_PASSWORD,resetDemo} from '../demo';import {errorText} from '../api';import Modal from './Modal.vue';import {RotateCcw,FlaskConical} from 'lucide-vue-next';
const auth=useAuth(),router=useRouter(),confirmReset=ref(false),busy=ref(false),error=ref('');
async function switchRole(event:Event){busy.value=true;try{const account=DEMO_ACCOUNTS.find(a=>a.role===(event.target as HTMLSelectElement).value)!;await auth.login(account.email,DEMO_PASSWORD);await router.replace('/');}catch(e){error.value=errorText(e);}finally{busy.value=false;}}
function restart(){try{resetDemo();window.location.assign('/login');}catch{error.value='No se pudo reiniciar la demo. Revisa el almacenamiento de tu navegador.';}}
</script>
<template><div class="demo-bar"><div class="demo-bar-description"><FlaskConical :size="18"/><div><strong>Demostración · No ingreses datos reales</strong><small>Cambios solo en este navegador. Archivos, mensajes y pagos simulados.</small></div></div><div class="demo-controls"><label>Vista<select :value="auth.role" @change="switchRole" :disabled="busy" aria-label="Cambiar perfil demo"><option value="admin">Contador</option><option value="client">Cliente</option></select></label><button class="button" @click="confirmReset=true"><RotateCcw :size="14"/>Reiniciar demo</button></div></div><p v-if="error" class="error" role="alert">{{error}}</p><Modal v-if="confirmReset" title="Reiniciar demostración" @close="confirmReset=false"><p>Se borrarán solo los cambios de esta demo en tu navegador y volverán las seis empresas de ejemplo.</p><div class="form-footer" style="margin-top:24px"><button class="button" @click="confirmReset=false">Conservar cambios</button><button class="button primary" @click="restart">Sí, reiniciar demo</button></div></Modal></template>
